folder = "C:\Users\Nickolay\Desktop\ITMO-courses\7_term\Discrete_control_systems\lab4\tex\images\";

T1 = 0.6;
T2 = 0.9;

kp = T1 + T2;
ki = 1;
kd = T1*T2;

names = {"forward", "backward", "tustin"};
labels = {"Forward Euler", "Backward Euler", "Tustin"};

q0s = [1 1 1];
noiseVar = 0.01;

T = 0.3;
T2p = T2;

c = [kp+kd/T -kp+ki*T-2*kd/T kd/T;
     kp+ki*T+kd/T -kp-2*kd/T kd/T;
     kp+ki*T/2+kd/T -kp+ki*T/2-2*kd/T kd/T];

num1 = q0s(1)*c(1,:);
num2 = q0s(2)*c(2,:);
num3 = q0s(3)*c(3,:);


q0c = 2;
T2p = T2;

simtime = 8;
out = sim("lab4_continuous.slx", simtime);

y = out.y_cont.Data;
t = out.y_cont.Time;

yt = 1-exp(-q0c*t);

f = figure;
f.Position = [100 100 900 500];

hold on;
plot(t, y, LineWidth=2);
plot(t, yt, LineStyle="--", LineWidth=2);
hold off;

legend({"$Simulink$", "$1-e^{-2t}$"}, Interpreter="latex");
grid on;
title("$Continuous\ PID\ control$", Interpreter="latex");
xlabel("$t,\;\mathrm{s}$", Interpreter="latex");
ylabel("$y(t)$", Interpreter="latex");

exportgraphics(f, fullfile(folder, "task1_continuous_pid.png"), Resolution=600);

maxError = max(abs(y-yt))


simtime = 25;
out1 = sim("lab4_pid.slx", simtime);

f = figure;
f.Position = [100 100 1200 1200];

for i = 1:3
    y = out1.get("y_"+names{i});
    u = out1.get("u_"+names{i});

    subplot(3,2,2*i-1);
    plot(y.Time,y.Data,LineWidth=2);
    yline(1,LineStyle="--");
    grid on;
    xlim([0 20]);
    title("$"+labels{i}+"$",Interpreter="latex");
    xlabel("$t,\;\mathrm{s}$",Interpreter="latex");
    ylabel("$y(t)$",Interpreter="latex");

    subplot(3,2,2*i);
    stairs(u.Time,u.Data,LineWidth=1);
    grid on;
    xlim([0 20]);
    title("$Control$",Interpreter="latex");
    xlabel("$t,\;\mathrm{s}$",Interpreter="latex");
    ylabel("$u(k)$",Interpreter="latex");
end

