exportgraphics(f,fullfile(folder,"task4_pole_compensation.png"),Resolution=600);


w0 = 0.9;
alpha = 0.05;
G0 = 2;
Q = 1.5;
R = 0.8;
h = 0.1;

Ak = [0 1; -w0^2 -2*alpha];
Bk = [0; w0^2];
Ck = [1 0];

sys = c2d(ss(Ak,Bk,Ck,0),h,"zoh");
Ah = sys.A;
Bh = sys.B;

Qx = Bh*Q*Bh';
P = dare(Ah',Ck',Qx,R);
Kk = P*Ck'/(Ck*P*Ck'+R);

Aobs = Ah*(eye(2)-Kk*Ck);
Bobs = Ah*Kk;
Cobs = Ck*(eye(2)-Kk*Ck);
Dobs = Ck*Kk;

simtime = 200;
out = sim("lab4_pitch.slx",simtime);

y = out.y_true.Data;
ym = out.y_meas.Data;
yh = out.y_est.Data;
t = out.y_true.Time;

f = figure;
f.Position = [100 100 1100 500];

hold on;
plot(t,ym,LineWidth=1);
plot(t,y,LineWidth=2);
hold off;

legend({"$y_m(k)$", "$y(k)$"},Interpreter="latex");
grid on;
xlim([0 100]);
title("$Irregular\ pitching$",Interpreter="latex");
xlabel("$t,\;\mathrm{s}$",Interpreter="latex");
ylabel("$y(k)$",Interpreter="latex");

