exportgraphics(f,fullfile(folder,"task7_pitching_kalman.png"),Resolution=600);

rmse_measurement = sqrt(mean((ym-y).^2));
rmse_kalman = sqrt(mean((yh-y).^2));


T = 0.3;
T2p = T2;
Rpid = 0.03;
Qpid = 0.01*eye(2);

A0 = [0 1; -1/(T1*T2) -(T1+T2)/(T1*T2)];
B0 = [0; 1/(T1*T2)];
C0 = [1 0];

sys = c2d(ss(A0,B0,C0,0),T,"zoh");
Ad = sys.A;
Bd = sys.B;

Ppid = dare(Ad',C0',Qpid,Rpid);
Kpid = Ppid*C0'/(C0*Ppid*C0'+Rpid);

Akal = Ad*(eye(2)-Kpid*C0);
Bkal = [Ad*Kpid Bd];
Ckal = C0*(eye(2)-Kpid*C0);
Dkal = [C0*Kpid 0];

c = [kp+kd/T -kp+ki*T-2*kd/T kd/T;
     kp+ki*T+kd/T -kp-2*kd/T kd/T;
     kp+ki*T/2+kd/T -kp+ki*T/2-2*kd/T kd/T];

num1 = q0s(1)*c(1,:);

simtime = 25;
out = sim("lab4_pid_kalman.slx",simtime);
y1 = out.y_raw.Data;
t1 = out.y_raw.Time;
u1 = out.u_raw.Data;
tu1 = out.u_raw.Time;

y2 = out.y_kal.Data;
t2 = out.y_kal.Time;
u2 = out.u_kal.Data;
tu2 = out.u_kal.Time;

f = figure;
f.Position = [100 100 900 900];

subplot(2,1,1);
hold on;
plot(t1,y1,LineWidth=2);
plot(t2,y2,LineWidth=2);
hold off;

legend({"$Without\ Kalman$", "$With\ Kalman$"},Interpreter="latex");
grid on;
xlim([0 20]);
title("$PID\ response$",Interpreter="latex");
xlabel("$t,\;\mathrm{s}$",Interpreter="latex");
ylabel("$y(t)$",Interpreter="latex");

subplot(2,1,2);
hold on;
stairs(tu1,u1,LineWidth=1);
stairs(tu2,u2,LineWidth=1);
hold off;

legend({"$Without\ Kalman$", "$With\ Kalman$"},Interpreter="latex");
grid on;
xlim([0 20]);
title("$Control$",Interpreter="latex");
xlabel("$t,\;\mathrm{s}$",Interpreter="latex");
ylabel("$u(k)$",Interpreter="latex");

exportgraphics(f,fullfile(folder,"task8_pid_kalman.png"),Resolution=600);
